CREATE OR REPLACE FUNCTION smarter_private.fn_fenced_manager_stopped_custody_park()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_snapshot jsonb;
  v_hand jsonb;
  v_tournament uuid;
  v_generation uuid;
  v_result jsonb;
BEGIN
  /* Every other writer - the service actor, a live manager, legacy-unmarked,
     and fn_park_stopped_time_bank_custody's own insert below - passes
     untouched. */
  IF current_setting('app.smarter_data_actor', true)
       IS DISTINCT FROM 'fenced-manager-stopped-custody' THEN
    RETURN NEW;
  END IF;

  v_snapshot := NEW.time_bank_snapshot;
  v_hand := v_snapshot -> 'handNumber';
  IF right(COALESCE(NEW.engine_instance, ''), 16) IS DISTINCT FROM ':stopped_custody'
     OR jsonb_typeof(v_snapshot) IS DISTINCT FROM 'object'
     OR (v_snapshot -> 'version') IS DISTINCT FROM '1'::jsonb
     OR jsonb_typeof(v_hand) IS DISTINCT FROM 'number'
     OR (v_hand::text)::numeric < 0
     OR (v_hand::text)::numeric <> trunc((v_hand::text)::numeric)
     OR jsonb_typeof(v_snapshot -> 'players') IS DISTINCT FROM 'object'
     OR jsonb_typeof(NEW.disconnect_states) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION
      'TOURNAMENT_MANAGER_FENCED: lease generation is no longer current'
      USING ERRCODE = '42501';
  END IF;

  BEGIN
    v_tournament := NULLIF(current_setting('app.smarter_tournament_id', true), '')::uuid;
    v_generation :=
      NULLIF(current_setting('app.smarter_tournament_lease_generation', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_tournament := NULL;
  END;
  IF v_tournament IS NULL OR v_generation IS NULL THEN
    RAISE EXCEPTION
      'TOURNAMENT_MANAGER_FENCED: lease generation is no longer current'
      USING ERRCODE = '42501';
  END IF;

  /* The custody is written as the process, by the reviewed refusing write.
     Transaction-local, and restored before anything else can read it. */
  PERFORM set_config('app.smarter_data_actor', 'service', true);
  v_result := public.fn_park_stopped_time_bank_custody(
    NEW.table_id,
    v_tournament,
    v_generation,
    (v_hand::text)::bigint,
    NEW.parked_at::text,
    NEW.disconnect_states,
    v_snapshot -> 'players',
    NEW.engine_instance
  );
  PERFORM set_config('app.smarter_data_actor', 'fenced-manager-stopped-custody', true);

  IF (v_result ->> 'ok') = 'true' THEN
    -- The function wrote the row. Suppress the raw ON CONFLICT DO UPDATE.
    RETURN NULL;
  END IF;
  RAISE EXCEPTION 'STOPPED_CUSTODY_REFUSED: %', COALESCE(v_result ->> 'refused', 'unknown')
    USING ERRCODE = '42501';
END
$function$

CREATE OR REPLACE FUNCTION smarter_private.f06_retired_origin_claim_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE origin smarter_private.f06_retired_manager_origins; transfer smarter_private.f06_manager_custody_transfers;
 admission smarter_private.f06_manager_custody_admissions; current_identity jsonb; current_heartbeat timestamptz;
BEGIN
 IF TG_OP='UPDATE' AND OLD.tournament_id IS DISTINCT FROM NEW.tournament_id
 AND smarter_private.f06_retired_origin_cohort(OLD.tournament_id) IS NOT NULL THEN
 RAISE EXCEPTION 'F06_RETIRED_EVENT_IDENTITY_CHANGED'; END IF;
 IF smarter_private.f06_retired_origin_cohort(NEW.tournament_id) IS NULL THEN RETURN NEW; END IF;
 PERFORM smarter_private.f06_retired_origin_lock(NEW.tournament_id);
 SELECT * INTO origin FROM smarter_private.f06_retired_manager_origins WHERE tournament_id=NEW.tournament_id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF NEW.lease_generation IS NOT DISTINCT FROM origin.origin_generation OR NEW.protocol_version IS DISTINCT FROM 2 THEN
 RAISE EXCEPTION 'F06_RETIRED_ORIGINAL_GENERATION_FENCED'; END IF;
 SELECT * INTO transfer FROM smarter_private.f06_manager_custody_transfers
 WHERE tournament_id=origin.tournament_id AND origin_generation=origin.origin_generation;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_RETIRED_TRANSFER_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_manager_custody_completions WHERE transfer_id=transfer.transfer_id) THEN RETURN NEW; END IF;
 IF NEW.lease_generation IS DISTINCT FROM transfer.successor_generation
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE tournament_id=NEW.tournament_id AND state='reserved') THEN
 RAISE EXCEPTION 'F06_RETIRED_SUCCESSOR_FENCED'; END IF;
 SELECT * INTO admission FROM smarter_private.f06_manager_custody_admissions WHERE transfer_id=transfer.transfer_id;
 IF FOUND THEN
 SELECT to_jsonb(l)-'heartbeat_at',l.heartbeat_at INTO current_identity,current_heartbeat FROM public.engine_tournament_leases l WHERE tournament_id=NEW.tournament_id;
 IF current_heartbeat IS NULL OR NOT isfinite(current_heartbeat)
 OR current_heartbeat<clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds())
 OR current_identity IS DISTINCT FROM admission.lease_identity OR NEW.instance_id IS DISTINCT FROM admission.lease_identity->>'instance_id'
 OR NEW.engine_version IS DISTINCT FROM admission.lease_identity->>'engine_version'
 OR (TG_OP='UPDATE' AND to_jsonb(NEW)-'heartbeat_at' IS DISTINCT FROM admission.lease_identity) THEN
 RAISE EXCEPTION 'F06_RETIRED_PARTIAL_PROCESS_CHANGED'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.f06_table_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE blocked boolean; reopening boolean;
BEGIN
 IF TG_OP='INSERT' THEN NEW.f06_lifecycle:=nextval('smarter_private.f06_lifecycle_seq');RETURN NEW; END IF;
 PERFORM smarter_private.f06_try_lane(OLD.tournament_id);
 SELECT EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE source_table_id=OLD.id AND state NOT IN ('acknowledged','withdrawn_before_manifest')) INTO blocked;
 IF TG_OP='DELETE' THEN
 IF blocked THEN RAISE EXCEPTION 'F06_PENDING_CUSTODY' USING ERRCODE='55000'; END IF; RETURN OLD; END IF;
 reopening:=(lower(COALESCE(OLD.status,'')) IN ('closed','completed','cancelled','finished') OR OLD.lifecycle='closed' OR COALESCE(OLD.is_deleted,false))
 AND NOT (lower(COALESCE(NEW.status,'')) IN ('closed','completed','cancelled','finished') OR NEW.lifecycle='closed' OR COALESCE(NEW.is_deleted,false));
 IF NEW.f06_lifecycle IS DISTINCT FROM OLD.f06_lifecycle THEN RAISE EXCEPTION 'F06_LIFECYCLE_IMMUTABLE' USING ERRCODE='55000'; END IF;
 IF blocked AND (reopening OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id) THEN
 RAISE EXCEPTION 'F06_PENDING_CUSTODY' USING ERRCODE='55000'; END IF;
 IF reopening THEN NEW.f06_lifecycle:=nextval('smarter_private.f06_lifecycle_seq'); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_lock_and_classify_tournament_table()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ids uuid[];
  v_parent_status text;
  v_launch_id uuid;
  v_launch_generation uuid;
  v_launch_completed_at timestamptz;
  v_proof_open boolean;
  v_needs_origin boolean := false;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.tournament_id IS NOT DISTINCT FROM OLD.tournament_id
     AND NEW.status IS NOT DISTINCT FROM OLD.status
     AND NEW.current_players IS NOT DISTINCT FROM OLD.current_players
     AND NEW.max_players IS NOT DISTINCT FROM OLD.max_players
     AND NEW.is_deleted IS NOT DISTINCT FROM OLD.is_deleted THEN
    RETURN NEW;
  END IF;

  v_ids := CASE
    WHEN TG_OP = 'INSERT' THEN ARRAY[NEW.tournament_id]
    WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.tournament_id]
    ELSE ARRAY[OLD.tournament_id, NEW.tournament_id]
  END;

  v_needs_origin := TG_OP = 'INSERT' AND NEW.tournament_id IS NOT NULL;
  IF TG_OP = 'UPDATE'
     AND OLD.tournament_id IS NULL
     AND NEW.tournament_id IS NOT NULL THEN
    v_needs_origin := true;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.tournament_id IS NOT NULL
     AND NEW.tournament_id IS DISTINCT FROM OLD.tournament_id THEN
    PERFORM *
      FROM public.fn_lock_tournament_launch_proof_parents(v_ids);
    RAISE EXCEPTION
      'TOURNAMENT_TABLE_ORIGIN_IMMUTABLE: table % cannot change tournament', OLD.id
      USING ERRCODE = '55000';
  END IF;

  IF NOT v_needs_origin THEN
    SELECT EXISTS (
      SELECT 1
        FROM public.tournaments t
        LEFT JOIN public.tournament_launch_receipts r
          ON r.tournament_id = t.id
       WHERE t.id = ANY(v_ids)
         AND (upper(t.status::text) = 'REGISTERING' OR r.completed_at IS NULL)
         AND (upper(t.status::text) = 'REGISTERING' OR r.tournament_id IS NOT NULL)
    ) INTO v_proof_open;
    IF NOT v_proof_open THEN
      RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
    END IF;
  END IF;

  IF v_needs_origin THEN
    SELECT locked.parent_status,
           locked.launch_id,
           locked.launch_lease_generation,
           locked.launch_completed_at
      INTO v_parent_status,
           v_launch_id,
           v_launch_generation,
           v_launch_completed_at
      FROM public.fn_lock_tournament_launch_proof_parents(
        ARRAY[NEW.tournament_id]
      ) AS locked;

    IF upper(v_parent_status) = 'RUNNING' THEN
      IF v_launch_id IS NOT NULL AND v_launch_completed_at IS NULL THEN
        RAISE EXCEPTION
          'TOURNAMENT_TABLE_ORIGIN_STATE_MISMATCH: RUNNING parent has an incomplete launch receipt'
          USING ERRCODE = '55000';
      END IF;
      INSERT INTO public.tournament_table_origins (
        table_id, tournament_id, origin_kind
      ) VALUES (
        NEW.id, NEW.tournament_id, 'capacity'
      );
    ELSIF upper(v_parent_status) = 'REGISTERING' THEN
      IF v_launch_id IS NULL THEN
        INSERT INTO public.tournament_table_origins (
          table_id, tournament_id, origin_kind
        ) VALUES (
          NEW.id, NEW.tournament_id, 'prelaunch'
        );
      ELSIF v_launch_completed_at IS NULL THEN
        INSERT INTO public.tournament_table_origins (
          table_id,
          tournament_id,
          origin_kind,
          launch_id,
          launch_lease_generation
        ) VALUES (
          NEW.id,
          NEW.tournament_id,
          'launch',
          v_launch_id,
          v_launch_generation
        );
      ELSE
        RAISE EXCEPTION
          'TOURNAMENT_TABLE_ORIGIN_STATE_MISMATCH: REGISTERING parent has a completed launch receipt'
          USING ERRCODE = '55000';
      END IF;
    ELSIF v_launch_id IS NULL THEN
      INSERT INTO public.tournament_table_origins (
        table_id, tournament_id, origin_kind
      ) VALUES (
        NEW.id, NEW.tournament_id, 'prelaunch'
      );
    ELSE
      RAISE EXCEPTION
        'STALE_TOURNAMENT_LAUNCH_TABLE: completed or inconsistent launch cannot create table %',
        NEW.id
        USING ERRCODE = '55000';
    END IF;
  ELSE
    PERFORM *
      FROM public.fn_lock_tournament_launch_proof_parents(v_ids);
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_tournament_table_close_requires_empty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_parent_status text;
BEGIN
  IF NEW.tournament_id IS NULL
     OR NOT (
       (lower(NEW.status::text) = 'closed'
        AND lower(OLD.status::text) IS DISTINCT FROM 'closed')
       OR (COALESCE(NEW.is_deleted, false) AND NOT COALESCE(OLD.is_deleted, false))
     ) THEN
    RETURN NEW;
  END IF;

  SELECT upper(t.status::text)
    INTO v_parent_status
    FROM public.tournaments t
   WHERE t.id = NEW.tournament_id;

  /* Terminal cleanup has its own atomic settlement/seat-release contracts.
     The dangerous path is a joinable or playing event whose table is being
     removed underneath a field that may still acquire a seat. */
  IF v_parent_status IN ('REGISTERING', 'RUNNING')
     AND EXISTS (
       SELECT 1
         FROM public.table_seats s
        WHERE s.table_id = OLD.id
          AND s.left_at IS NULL
     ) THEN
    RAISE EXCEPTION
      'TOURNAMENT_TABLE_CLOSE_NOT_EMPTY: table % still has a live seat', OLD.id
      USING ERRCODE = '23514';
  END IF;

  IF lower(NEW.status::text) = 'closed' THEN
    NEW.current_players := 0;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cancelled_tournament_evidence_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_tournament_id uuid;
BEGIN
 IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;
  IF TG_OP<>'INSERT' THEN
    v_old_tournament_id:=NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  END IF;
  IF TG_OP<>'DELETE' THEN
    v_new_tournament_id:=NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;
  END IF;
  IF TG_OP='UPDATE' AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME
      USING ERRCODE='55000';
  END IF;
  v_tournament_id:=COALESCE(v_new_tournament_id,v_old_tournament_id);
  IF v_tournament_id IS NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME='chip_ledger' AND TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id=v_tournament_id FOR KEY SHARE;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=v_tournament_id) THEN
    RAISE EXCEPTION 'cancelled tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_publish_member_record_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u uuid;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
   IF NEW.name IS NOT DISTINCT FROM OLD.name THEN RETURN NULL; END IF;
   FOR u IN SELECT DISTINCT user_id FROM public.club_members WHERE club_id=NEW.id LOOP
     PERFORM public.fn_publish_member_record_user(u);
   END LOOP;
 ELSE
   IF ROW(NEW.status,NEW.club_id,NEW.name,NEW.stakes,NEW.tournament_id,NEW.is_deleted) IS NOT DISTINCT FROM ROW(OLD.status,OLD.club_id,OLD.name,OLD.stakes,OLD.tournament_id,OLD.is_deleted) THEN RETURN NULL; END IF;
   FOR u IN SELECT DISTINCT user_id FROM public.table_seats WHERE table_id=NEW.id AND left_at IS NULL LOOP
     PERFORM public.fn_publish_member_record_user(u);
   END LOOP;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_midway_cash_rake_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_union uuid; v_asset text;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    IF NEW.asset='diamonds' THEN RETURN NEW; END IF;
    IF NEW.union_id='fade0000-0000-0000-0000-000000000001'::uuid
       OR NEW.id='fade0000-0000-0000-0000-000000000001'::uuid THEN
      NEW.rake_cap := CASE WHEN NEW.rake_cap > 2.5 THEN 2.5 ELSE NEW.rake_cap END;
      IF NEW.default_rake_percent > 10 THEN
        RAISE EXCEPTION 'Midway Cash Rake Is Limited To 10 Percent And 2.5 BB';
      END IF;
    END IF;
  ELSE
    IF NEW.tournament_id IS NOT NULL THEN RETURN NEW; END IF;
    SELECT c.union_id,c.asset INTO v_union,v_asset FROM public.clubs c WHERE c.id=NEW.club_id;
    IF v_asset='diamonds' THEN RETURN NEW; END IF;
    IF NEW.union_id='fade0000-0000-0000-0000-000000000001'::uuid
       OR v_union='fade0000-0000-0000-0000-000000000001'::uuid THEN
      NEW.rake_cap_bb := CASE WHEN NEW.rake_cap_bb > 2.5 THEN 2.5 ELSE NEW.rake_cap_bb END;
      IF NEW.rake_percent > 10 THEN
        RAISE EXCEPTION 'Midway Cash Rake Is Limited To 10 Percent And 2.5 BB';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_guard_arena_structure()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_asset text;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    IF TG_OP='UPDATE' AND (NEW.asset,NEW.is_platform) IS DISTINCT FROM (OLD.asset,OLD.is_platform) THEN
      RAISE EXCEPTION 'Arena Asset Is Immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.asset='diamonds' AND auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false) THEN
      RAISE EXCEPTION 'Diamond Arena Requires Platform Operations' USING ERRCODE='42501';
    END IF;
    -- THE ARENA BELONGS TO THE SYSTEM (2026-09-30, decided by Claude on Dan's
    -- delegation): a Diamond club is owned by the system account, which nobody
    -- signs in as, so no door that trusts a club's owner admits a person to
    -- the arena. Platform staff run it through the staff doors.
    IF NEW.asset='diamonds' AND NEW.owner_id IS DISTINCT FROM '00000000-0000-0000-0000-000000000001'::uuid THEN
      RAISE EXCEPTION 'The Diamond Arena Belongs To The System' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT asset INTO v_asset FROM public.clubs WHERE id=NEW.club_id;
  IF TG_TABLE_NAME='club_members' AND TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
     AND EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset='diamonds') THEN
    RAISE EXCEPTION 'Diamond Participation Cannot Become A Chip Membership' USING ERRCODE='23514';
  END IF;
  -- Branch before resolving fields: membership rows do not have union_id.
  IF TG_TABLE_NAME IN ('tables','tournaments') THEN
    IF TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
       AND (EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset IS DISTINCT FROM v_asset)
         OR (OLD.club_id IS NULL AND OLD.union_id IS NOT NULL AND v_asset='diamonds')) THEN
      RAISE EXCEPTION 'Game Asset Is Immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF v_asset='diamonds' THEN
    IF TG_TABLE_NAME='club_members' THEN
      IF TG_OP='INSERT' OR NEW.role IS DISTINCT FROM 'player' OR NEW.status IS DISTINCT FROM 'automatic'
         OR NEW.agent_id IS NOT NULL OR NEW.parent_agent_id IS NOT NULL
         OR coalesce(NEW.chip_balance,0)<>0 OR coalesce(NEW.credit_limit,0)<>0
         OR coalesce(NEW.credit_used,0)<>0 OR coalesce(NEW.promo_balance,0)<>0
         OR coalesce(NEW.held_chips,0)<>0 THEN
        RAISE EXCEPTION 'Diamond Membership Is Automatic And Has No Chip Wallet Or Hierarchy' USING ERRCODE='23514';
      END IF;
    ELSIF TG_TABLE_NAME='union_clubs' THEN
      RAISE EXCEPTION 'Diamond Arena Cannot Join A Union' USING ERRCODE='23514';
    ELSIF auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false)
       -- DIAMOND PHASE 8: a player's entry, add-on and withdrawal move the
       -- play-state counters through the estate's doors; the structure is
       -- still platform operations only.
       AND NOT (TG_OP='UPDATE' AND TG_TABLE_NAME IN ('tournaments','tables')
                -- DIAMOND PHASE 11: a stored generated column is NULL in NEW before
                -- the row is written, and follows the base columns compared here; it
                -- is left out, or a player's buy-in reads as a structural change.
                AND (to_jsonb(NEW) - public.fn_poker_diamond_play_state_columns(TG_TABLE_NAME)
                       - ARRAY(SELECT a.attname::text FROM pg_catalog.pg_attribute a
                                WHERE a.attrelid = TG_RELID AND a.attgenerated <> '' AND NOT a.attisdropped))
                  = (to_jsonb(OLD) - public.fn_poker_diamond_play_state_columns(TG_TABLE_NAME)
                       - ARRAY(SELECT a.attname::text FROM pg_catalog.pg_attribute a
                                WHERE a.attrelid = TG_RELID AND a.attgenerated <> '' AND NOT a.attisdropped))) THEN
      RAISE EXCEPTION 'Diamond Games Require Platform Operations' USING ERRCODE='42501';
    ELSIF NEW.union_id IS NOT NULL THEN
      RAISE EXCEPTION 'Diamond Games Cannot Belong To A Union' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

